String nid()=>DateTime.now().microsecondsSinceEpoch.toString(); String today()=>DateTime.now().toIso8601String().substring(0,10);
void startRentFlow(){WidgetsFlutterBinding.ensureInitialized();runApp(const App());}
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'RentFlow',theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:primary),inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12),borderSide:const BorderSide(color:border)),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(12),borderSide:const BorderSide(color:border)))),home:const Splash());}
class Splash extends StatefulWidget{const Splash({super.key});@override State<Splash> createState()=>_SplashState();}class _SplashState extends State<Splash>{@override void initState(){super.initState();Future.delayed(const Duration(milliseconds:1400),(){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Shell()));});}@override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.white,body:Center(child:Padding(padding:const EdgeInsets.all(18),child:SvgPicture.asset('assets/rentflow_splash.svg',width:360))));}
class DB extends ChangeNotifier{late SharedPreferences p;List<Map<String,dynamic>> shops=[];int active=0;bool get has=>shops.isNotEmpty;Map<String,dynamic> get shop=>has?shops[active]:{};List<Map<String,dynamic>> get items=>rows('items');List<Map<String,dynamic>> get customers=>rows('customers');List<Map<String,dynamic>> get issues=>rows('issues');List<Map<String,dynamic>> get returns=>rows('returns');List<Map<String,dynamic>> rows(String k){final v=shop[k];if(v is! List)return[];return v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}Future<void> load()async{p=await SharedPreferences.getInstance();try{final r=jsonDecode(p.getString('rf_shops')??'[]');if(r is List)shops=r.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];}active=p.getInt('rf_active')??0;if(active>=shops.length)active=0;notifyListeners();}Future<void> save()async{await p.setString('rf_shops',jsonEncode(shops));await p.setInt('rf_active',active);notifyListeners();}Future<void> addShop(String n,String o,String m,String a)async{shops.add({'id':nid(),'name':n,'owner':o,'mobile':m,'address':a,'items':[],'customers':[],'issues':[],'returns':[]});active=shops.length-1;await save();}Future<void> editShop(int i,String n,String o,String m,String a)async{shops[i]['name']=n;shops[i]['owner']=o;shops[i]['mobile']=m;shops[i]['address']=a;await save();}Future<void> delShop(int i)async{shops.removeAt(i);if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;await save();}Future<void> select(int i)async{active=i;await save();}Future<void> add(String k,Map<String,dynamic> v)async{(shop[k] as List).add(v);await save();}Future<void> edit(String k,int i,Map<String,dynamic> v)async{(shop[k] as List)[i]=v;await save();}Future<void> del(String k,int i)async{(shop[k] as List).removeAt(i);await save();}}
class Shell extends StatefulWidget{const Shell({super.key});@override State<Shell> createState()=>_ShellState();}class _ShellState extends State<Shell>{final db=DB();@override void initState(){super.initState();db.load();}@override Widget build(BuildContext c)=>AnimatedBuilder(animation:db,builder:(_,__)=>db.p==null?const Scaffold(body:Center(child:CircularProgressIndicator())):Home(db:db));}
