class ShopForm extends StatefulWidget{final DB db;final int? index;const ShopForm({super.key,required this.db,this.index});@override State<ShopForm> createState()=>_ShopFormState();}class _ShopFormState extends State<ShopForm>{late TextEditingController n,o,m,a;@override void initState(){super.initState();final x=widget.index==null?<String,dynamic>{}:widget.db.shops[widget.index!];n=TextEditingController(text:'${x['name']??''}');o=TextEditingController(text:'${x['owner']??''}');m=TextEditingController(text:'${x['mobile']??''}');a=TextEditingController(text:'${x['address']??''}');}@override void dispose(){n.dispose();o.dispose();m.dispose();a.dispose();super.dispose();}Future<void> save()async{if(n.text.trim().isEmpty)return;if(widget.index==null)await widget.db.addShop(n.text.trim(),o.text.trim(),m.text.trim(),a.text.trim());else await widget.db.editShop(widget.index!,n.text.trim(),o.text.trim(),m.text.trim(),a.text.trim());if(mounted)Navigator.pop(context);}@override Widget build(BuildContext c)=>Page(widget.index==null?'Register Shop':'Edit Shop',Column(children:[F('Shop / Company Name',n),F('Owner Name',o),F('Mobile Number',m,n:true),F('Shop Address',a,lines:3),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:Text(widget.index==null?'Save Shop':'Update Shop')))]));}
