class ItemForm extends StatefulWidget{final DB db;final int? index;const ItemForm({super.key,required this.db,this.index});@override State<ItemForm> createState()=>_ItemFormState();}class _ItemFormState extends State<ItemForm>{late TextEditingController code,name,unit,qty;@override void initState(){super.initState();final x=widget.index==null?<String,dynamic>{}:widget.db.items[widget.index!];code=TextEditingController(text:'${x['code']??''}');name=TextEditingController(text:'${x['name']??''}');unit=TextEditingController(text:'${x['unit']??'pcs'}');qty=TextEditingController(text:'${x['quantity']??0}');}@override void dispose(){code.dispose();name.dispose();unit.dispose();qty.dispose();super.dispose();}Future<void> save()async{if(name.text.trim().isEmpty)return;final v={'id':widget.index==null?nid():widget.db.items[widget.index!]['id'],'code':code.text,'name':name.text,'unit':unit.text,'quantity':int.tryParse(qty.text)??0};if(widget.index==null)await widget.db.add('items',v);else await widget.db.edit('items',widget.index!,v);if(mounted)Navigator.pop(context);}@override Widget build(BuildContext c)=>Page(widget.index==null?'New Item':'Edit Item',Column(children:[F('Item Code',code),F('Item Name / Description',name),Row(children:[Expanded(child:F('Unit',unit)),const SizedBox(width:8),Expanded(child:F('Opening Quantity',qty,n:true))]),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Save Item')))]));}
