class Issue extends StatefulWidget{final DB db;const Issue({super.key,required this.db});@override State<Issue> createState()=>_IssueState();}class _IssueState extends State<Issue>{late TextEditingController inv,date,addr;String? customer;final lines=<Map<String,dynamic>>[];@override void initState(){super.initState();inv=TextEditingController(text:'RF-${DateTime.now().millisecondsSinceEpoch}');date=TextEditingController(text:today());addr=TextEditingController();}@override void dispose(){inv.dispose();date.dispose();addr.dispose();super.dispose();}Future<void> chooseCustomer()async{final x=await goResult(context,Picker(title:'Select Customer / Party',rows:widget.db.customers,icon:Icons.person_outline));if(x!=null)setState((){customer='${x['id']}';addr.text='${x['address']??''}';});}Future<void> chooseItem()async{final x=await goResult(context,Picker(title:'Select Inventory Item',rows:widget.db.items,icon:Icons.inventory_2_outlined));if(x!=null)setState(()=>lines.add({'itemId':x['id'],'name':x['name'],'quantity':1,'rentDays':1}));}String cname(){for(final x in widget.db.customers){if('${x['id']}'==customer)return '${x['name']}';}return 'Select Customer / Party';}Future<void> save()async{if(customer==null||lines.isEmpty)return;await widget.db.add('issues',{'id':nid(),'invoice':inv.text,'date':date.text,'customer':cname(),'customerId':customer,'address':addr.text,'lines':lines});if(mounted)Navigator.pop(context);} @override Widget build(BuildContext c)=>Page('Issue Entry',Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:F('Invoice / Issue No.',inv)),const SizedBox(width:8),Expanded(child:F('Issue Date',date))]),ListTile(tileColor:Colors.white,title:Text(cname(),style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:const Text('Customer / Party'),trailing:const Icon(Icons.arrow_drop_down),onTap:chooseCustomer),F('Site / Delivery Address',addr,lines:2),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('ITEM ENTRIES',style:TextStyle(color:primary,fontWeight:FontWeight.w900)),FilledButton.icon(onPressed:chooseItem,icon:const Icon(Icons.add),label:const Text('Add Item'))]),for(final x in lines)Card(elevation:0,child:ListTile(title:Text('${x['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('Issued Qty: ${x['quantity']} • Rent Days: ${x['rentDays']}'),trailing:IconButton(onPressed:()=>setState(()=>lines.remove(x)),icon:const Icon(Icons.delete_outline,color:Colors.red)))),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Save Issue Entry'))]));}}
